class C
{
    void M1(C c1, C c2)
    {
        int x, y;
        _ = c1?.M(out x, out y) ?? c2?.M(out x, out y) ?? true
            ? x.ToString() // 1
            : y.ToString();
    }

    void M2(C c1, C c2)
    {
        int x, y;
        _ = c1?.M(out x, out y) ?? c2?.M(out x, out y) ?? false
            ? x.ToString()
            : y.ToString(); // 2;
    }

    bool M(out int x, out int y) { x = 42; y = 42; return true; }
}

